from pathlib import Path
import hashlib,json
root=Path.cwd(); repo=root.parent
manifests=[json.loads(p.read_text(encoding='utf-8')) for p in (root/'assets/free_works').glob('*.source.json')]
assert len(manifests)==15
manifests.sort(key=lambda m:(0 if 'lazarillo' in m['id'] else 1 if 'vida-sueno' in m['id'] else 2,m['title']))
assets=list((root/'assets/free_works').glob('*.txt'))
web=root/'build/web'
for path in (root/'assets/free_works').iterdir():
 if path.is_file(): assert (web/'assets/assets/free_works'/path.name).read_bytes()==path.read_bytes(), 'Stale web asset: '+path.name
build=json.loads((root/'tool/collection_web_build_result.json').read_text(encoding='utf-8-sig'))
web_bytes=sum(p.stat().st_size for p in web.rglob('*') if p.is_file())
lines=['INFORME AMPLIACIÓN BIBLIOTECA GRATUITA — CAPÍTULO 0','Fecha: 16 de noviembre de 2026. Defensa: 18 de noviembre de 2026.','', 'RESULTADO REAL','15 obras completas en español: 2 conservadas y 13 adicionales. No se añadieron fichas de relleno ni extractos. Incluye novela, teatro, cuentos/leyendas y poesía. Los diez relatos de Bécquer se cuentan como obras breves autónomas completas, no como diez novelas ni como una colección integral de todas sus Leyendas.','', 'PROTECCIÓN Y ALCANCE','Rama feature/resiliencia-gutendex-20261116; HEAD c049e30. No se ejecutaron pull, merge, reset, clean, checkout, commit, push ni PR.','Parche inicial de cambios tracked: respaldos/biblioteca_pre_ampliacion_20261116_171922/tracked.patch. La comprobación del respaldo detectó que la primera copia, por separadores de ruta, solo había guardado ese parche; se completó con 94 archivos copiados y verificados por SHA-256, con recibos en backup_receipts.json. El snapshot de archivos corresponde al momento de esa comprobación, no a una copia previa de todos los archivos sin seguimiento. No se imprimió contenido privado ni se modificó la configuración privada.','Los TXT, manifiestos y scripts originales de Lazarillo y La vida es sueño se conservaron. SHA-256 de ambos TXT comprobado contra sus manifiestos originales. Los cambios tracked previos de resiliencia Gutendex y pubspec.yaml coinciden con el parche inicial; solo se adaptó adicionalmente la prueba de navegación para desplazarse por la lista más larga.','El lector compartido, Home, Gemini, Biblioteca personal, Perfil, Writer, Clubes, Maps, Firebase, Neon, backend y tema global no se modificaron. No se añadieron dependencias. La configuración de assets ya incluía assets/free_works/ y se reutilizó sin cambiarla.','', 'TÍTULOS, AUTORES, EDICIONES Y FUENTES']
for i,m in enumerate(manifests,1):
 lines += [f"{i}. {m['title']} — {m['author']}", '   Edición: '+m['edition'], '   Fuente: '+m['source'], f"   Tamaño: {m['bytes']} bytes; {m['utf16_units']} unidades UTF-16.", '   SHA-256: '+m['sha256']]
 if m.get('edition_evidence'): lines+=['   Evidencia editorial: '+m['edition_evidence']]
 if m.get('notes'): lines+=['   Nota: '+m['notes']]
lines += ['', 'DERECHOS Y PROCEDENCIA','Obras originales de dominio público en Chile. Los autores nuevos fallecieron en 1635 (Lope de Vega), 1870 (Bécquer) y 1891 (Alarcón), fuera del plazo de vida más 70 años. Las condiciones preexistentes de las dos ediciones iniciales permanecen. No se incorporaron traducciones modernas ni material editorial protegido no verificado.','Base consultada: https://www.bcn.cl/leychile/navegar?idNorma=28933 (Ley 17.336, artículos 10 y 11); https://www.propiedadintelectual.gob.cl/faq','Transcripción/conversión: CC BY-SA 4.0 cuando corresponda; se identifica autor, comunidad Wikisource, fuente, cambios, licencia e historiales. Se mantienen las condiciones de compartir igual para las copias. https://es.wikisource.org/wiki/Wikisource:Derechos_de_autor y https://creativecommons.org/licenses/by-sa/4.0/','Cada manifiesto .source.json contiene revisión, fecha, secciones, principio y final, tamaño, SHA-256 del texto y de las secciones. Para nuevas obras se conserva también la respuesta HTML fuente exacta y su huella en tool/free_work_sources. La revisión de una página no congela sus transclusiones: la instantánea con SHA permite reproducir la conversión recibida. En Rimas la revisión ancla es la del índice del escaneo, no una supuesta revisión de todas las páginas; se identifican rango exportado e historiales de sus 78 páginas.','Los relatos proceden de los tomos de Obras de Bécquer (1885). Rimas: 76 poemas I–LXXVI, incluyendo el último completo. Fuenteovejuna: personajes y tres actos. El capitán Veneno: cuatro partes y 27 capítulos. Estas dos últimas son ediciones digitales de revisión identificada, sin edición impresa base documentada.','', 'TAMAÑOS Y CARGA',f"TXT completos: {sum(p.stat().st_size for p in assets):,} bytes.",f"Manifiestos empaquetados: {sum(p.stat().st_size for p in (root/'assets/free_works').glob('*.source.json')):,} bytes.",f"Metadatos Dart adicionales: {(root/'lib/features/gutendex/models/prepared_free_works.dart').stat().st_size:,} bytes.",'La lista usa metadatos pequeños; los textos solo se leen al pulsar Leer ahora. Las pruebas verifican cero cargas del cuerpo al listar y una carga por apertura. No se hace búsqueda remota ni se descargan obras desde Wikisource/Gutendex durante la lectura. En Web el asset se sirve desde el mismo origen de la aplicación.','Todas las obras cumplen 8 MiB y 2.097.152 unidades UTF-16; ninguna se truncó ni dividió para eludir límites.','', 'PRUEBAS Y COMPILACIÓN','flutter test --no-pub: 437 aprobadas, 1 omitida por la condición preexistente !kIsWeb de firebase_web_auth_test.dart. Duración informada: 3 min 58 s. Log: android/tool/collection_full_tests.log.','Durante la primera ejecución se detectaron dos pruebas de navegación móvil que buscaban el botón remoto antes de hacer scroll. Se adaptó el desplazamiento, conservando las aserciones de navegación, consultas y retorno. La nueva prueba también detectó que había que conservar el controlador del buscador al reciclar widgets; se corrigió en FreeLibraryScreen. La ejecución final completa no tuvo fallos.','Después de corregir exclusivamente los enlaces de atribución de Rimas, se repitieron las seis pruebas de la colección: todas aprobadas, incluidos hashes, los 15 assets y dos lecturas reales en cada tamaño móvil. El cuerpo literario de Rimas no cambió. Log: android/tool/collection_final_integrity_tests.log.','python tool/verify_collection.py: PASS de 15 obras; IDs y textos distintos, SHA-256, cuerpo, secciones ordenadas, inicio y final, UTF-8, tamaños y fuente conservada.','flutter analyze --no-pub: No issues found (19,3 s en la ejecución final). Log: android/tool/collection_analyze.log.','git diff --check: exit 0. Git avisa sobre conversión LF/CRLF de archivos preexistentes; no reporta errores de espacios.','Pruebas funcionales: búsqueda local por título y autor con/sin acentos; sin resultados; filtro de género; una ruta de asset sin revisión completa no promete lectura; dos textos reales distintos; scroll; aumento/disminución de letra y reflujo con conservación de posición; regreso y búsqueda conservada; catálogo remoto opcional y fallo remoto sin eliminar obras locales.','Tamaños 320x568, 360x640 y 390x844, sin overflow observado por tests. El lector original tiene además pruebas en tema claro/oscuro y escala accesible.','Regresiones: suite existente de Home, recomendaciones Gemini, catálogo, Biblioteca personal y MainShell aprobada. Writer, Clubes y Maps permanecen sin cambios; se construye el MainShell en las pruebas existentes, pero no se declara una validación end-to-end de sus servicios externos ni una sesión manual de Chrome de todos esos módulos.',f"flutter build web --no-pub: exit {build['exit_code']}; compilación informada 260,0 s; tiempo total medido {build['elapsed_seconds']:.2f} s.",f"build/web: {web_bytes:,} bytes sin comprimir (incluye motores/variantes CanvasKit); main.dart.js: {(web/'main.dart.js').stat().st_size:,} bytes.",'Se compararon byte a byte los 15 TXT y sus 15 manifiestos empaquetados con los assets definitivos: coinciden. Flutter emitió la recomendación informativa de probar --wasm tras un dry run exitoso; no hubo error de compilación. No se midieron FPS, memoria, tiempo real de apertura ni transferencia comprimida en navegador.','', 'LIMITACIONES','Colección de 15 obras, no de miles. Se priorizó integridad frente a cantidad. Fuenteovejuna y El capitán Veneno no tienen edición impresa base identificada. Las transcripciones pueden contener erratas y ortografía histórica: no se presentan como ediciones críticas corregidas. Se pierde tipografía del impreso, no contenido literario.','Marianela se descartó porque el rango consultado tenía lagunas de transcripción. Varias páginas candidatas eran índices o enlaces a ediciones inexistentes. La exportación inicial corta de Rimas no se ofreció; se verificó hasta la última estrofa antes de incorporarla. Estas fuentes de investigación no aparecen como libros legibles.','La API respondió inicialmente 403 en el entorno restringido y 429 al investigar candidatas. No se eludieron bloqueos: se pausó la consulta y se adoptaron solicitudes seriales de 12 s y detención ante errores, sin reintentos automáticos ni rastreo masivo. Las fuentes guardadas evitan nuevas consultas al preparar. WSexport no se necesitó: la exportación utilizada es MediaWiki parse con un rango explícito de páginas.','La prueba Firebase exclusiva de Web no se ejecutó en la VM, ni se realizó autenticación real o validación manual del navegador.','', 'CÓMO PROBAR VARIAS LECTURAS EN CHROME','Desde android: flutter run -d chrome --no-pub (usar los mismos parámetros locales autorizados con los que habitualmente se ejecuta el proyecto; no publicar ni copiar secretos).','Entrar en el modo habitual/invitado, abrir desde Home el acceso al catálogo y comprobar Biblioteca gratuita con 15 lecturas disponibles.','Buscar "alarcon"; abrir El capitán Veneno, pulsar Leer ahora y verificar comienzo, distintas partes y final. Aumentar letra, desplazar y regresar dos veces: la búsqueda debe seguir escrita.','Borrar búsqueda, filtrar Poesía y abrir Rimas: debe comenzar con I / Yo sé un himno gigante y extraño y terminar el poema LXXVI antes de los créditos.','Elegir Todos los géneros, buscar "monte", abrir El monte de las ánimas: debe ser un texto distinto; probar también Fuenteovejuna y los dos libros originales.','En DevTools emular 320x568, 360x640 y 390x844: verificar ausencia de overflow, desplazamiento y regreso. Inspeccionar Network: las lecturas locales no deben solicitar gutendex.com, gutenberg.org ni es.wikisource.org. Web sirve TXT desde assets del propio origen; no se abre otra pestaña ni se exige importar TXT.','El botón Consultar catálogo en línea está al final de la lista y sigue siendo opcional. Si falla, regresar y seguir leyendo las obras locales. Para una prueba offline del navegador, cargar previamente los recursos de la aplicación; el empaquetado de assets no equivale a implementar una PWA offline nueva.','', 'CRECIMIENTO FUTURO','Diseño documentado en android/tool/README_FREE_WORKS.md: catálogo de metadatos versionado/paginado, identificador estable por edición, clasificación opcional, estado de integridad y procedencia, licencia/atribución, content.kind bundledAsset o authorizedDownload, versión, URL autorizada, bytes, unidades UTF-16 y SHA-256.','Faltan servicio propio autorizado, catálogo y búsquedas paginados, descarga bajo demanda, verificación antes de lectura, caché por plataforma con cuota/LRU, promoción atómica, cancelación y reintentos explícitos, autenticidad del manifiesto, actualizaciones/retirada y pruebas de escala. El adaptador futuro produciría ReaderSource sin reconstruir el lector. No se implementaron backend, alojamiento externo ni API universal.','', 'ENTREGA DETENIDA EN ESTE BLOQUE','No se iniciaron otros módulos. No hay commit, push ni PR.']
output=repo/'INFORME_AMPLIACION_BIBLIOTECA_GRATUITA_CAPITULO0.txt';output.write_text('\n'.join(lines)+'\n',encoding='utf-8');print(str(output));print('TXT bytes',sum(p.stat().st_size for p in assets),'Web bytes',web_bytes)
